import React, { createContext, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { apiFetch } from "./api";
import { useAuth } from "./AuthContext";
import { h } from "./h";

const NotificationContext = createContext({
  unreadCount: 0,
  loading: false,
  refresh: async () => {},
  loadList: async () => [],
  markRead: async (_id) => {},
  markAllRead: async () => {}
});

export function NotificationProvider({ children }) {
  const { accessToken } = useAuth();
  const [unreadCount, setUnreadCount] = useState(0);
  const [loading, setLoading] = useState(false);

  const authHeaders = useMemo(
    () => (accessToken ? { headers: { Authorization: `Bearer ${accessToken}` } } : null),
    [accessToken]
  );

  const refresh = useCallback(async () => {
    if (!authHeaders) {
      setUnreadCount(0);
      return;
    }
    try {
      const d = await apiFetch("/api/notifications/summary", authHeaders);
      setUnreadCount(Number(d.unreadCount) || 0);
    } catch {
      setUnreadCount(0);
    }
  }, [authHeaders]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  useEffect(() => {
    if (!accessToken) return;
    const id = setInterval(refresh, 45000);
    const onVis = () => {
      if (document.visibilityState === "visible") refresh();
    };
    document.addEventListener("visibilitychange", onVis);
    return () => {
      clearInterval(id);
      document.removeEventListener("visibilitychange", onVis);
    };
  }, [accessToken, refresh]);

  const loadList = useCallback(async () => {
    if (!authHeaders) return [];
    setLoading(true);
    try {
      const d = await apiFetch("/api/notifications", authHeaders);
      return d.notifications || [];
    } catch {
      return [];
    } finally {
      setLoading(false);
    }
  }, [authHeaders]);

  const markRead = useCallback(
    async (nid) => {
      if (!authHeaders || !nid) return;
      try {
        await apiFetch(`/api/notifications/${nid}/read`, { method: "POST", ...authHeaders });
        await refresh();
      } catch {
        /* ignore */
      }
    },
    [authHeaders, refresh]
  );

  const markAllRead = useCallback(async () => {
    if (!authHeaders) return;
    try {
      await apiFetch("/api/notifications/read-all", { method: "POST", ...authHeaders });
      await refresh();
    } catch {
      /* ignore */
    }
  }, [authHeaders, refresh]);

  const value = useMemo(
    () => ({ unreadCount, loading, refresh, loadList, markRead, markAllRead }),
    [unreadCount, loading, refresh, loadList, markRead, markAllRead]
  );

  return h(NotificationContext.Provider, { value }, children);
}

export function useNotifications() {
  return useContext(NotificationContext);
}
